using System;
using System.IO;
using System.Text;
using System.Text.RegularExpressions;
using System.Collections.Generic;
using C=HubSshMaintenanceCommon;
public static class HubSshMaintenanceEntry {
  public static Dictionary<string,object> Request(){string value=Environment.GetEnvironmentVariable("HUB_SSH_MAINTENANCE_REQUEST");Environment.SetEnvironmentVariable("HUB_SSH_MAINTENANCE_REQUEST",null);C.Require(value!=null&&value.Length<=32000,"REQUEST_MISSING");return C.Parse(C.Utf8.GetString(Convert.FromBase64String(value)));}
  public static int Fail(Exception error,bool raw){string code=C.Error(error);Console.Error.WriteLine("HUB_MAINTENANCE_ERROR:"+code);if(!raw)Console.WriteLine(C.Canon(new Dictionary<string,object>{{"ok",false},{"code",code}}));return 125;}
  [STAThread] public static int Main(){try{var req=Request();string mode=C.Str(req,"mode",32),fault=null;Dictionary<string,object> recovery=null;if(req.ContainsKey("recoveryGrant")){recovery=req["recoveryGrant"] as Dictionary<string,object>;C.Require(recovery!=null,"RECOVERY_GRANT_REJECTED");req.Remove("recoveryGrant");C.Require(mode=="resume"||mode=="rollback"||mode=="recover-pointer","RECOVERY_MODE_REJECTED");}
#if HUB_SSH_MAINTENANCE_TEST
      if(req.ContainsKey("faultAt")){C.Fields(req,"mode","manifest","faultAt");fault=C.Str(req,"faultAt",64);C.Require(Regex.IsMatch(fault,"^AFTER_(SOURCE_INTENT|DESTINATION_INTENT|INTENTS|CREDENTIAL_WRITE|PENDING_RECEIPT|PROBE_1|PROBE_2|ACTIVATION_INTENT|POINTER|POINTER_DISPLACE|ACTIVATION_RECEIPT|DELETE_INTENT|SOURCE_DELETE|TOMB|COMPLETE|ROLLBACK_INTENT|ROLLBACK_POINTER|ROLLBACK_DISPLACE|ROLLBACK_DELETE|ROLLBACK_RECORD|POINTER_RECOVERY_INTENT|POINTER_RECOVERY_WRITE)$"),"FAULT_POINT_REJECTED");}else
#endif
      C.Fields(req,"mode","manifest");
      C.Require(mode=="migrate"||mode=="resume"||mode=="status"||mode=="rollback"||mode=="recover-pointer"
#if HUB_SSH_MAINTENANCE_TEST
        ||mode=="fixture-inspect"||mode=="fixture-cleanup"
#endif
        ,"MODE_REJECTED");using(var state=new HubSshMaintenanceState(req["manifest"] as Dictionary<string,object>,fault,true)){state.SetRecovery(recovery,mode);
#if HUB_SSH_MAINTENANCE_TEST
        if(fault!=null)C.Require((string)state.Source["host"]=="127.0.0.1"&&(string)state.Source["user"]=="fixture","FIXTURE_TARGET_REJECTED");
        if(mode=="fixture-inspect"||mode=="fixture-cleanup"){Console.WriteLine(C.Canon(state.Fixture(mode=="fixture-cleanup")));return 0;}
#endif
        var result=mode=="status"?state.Status():mode=="rollback"?state.Rollback():mode=="recover-pointer"?state.RecoverPointer():state.Migrate(mode);Console.WriteLine(C.Canon(result));return 0;
      }}catch(Exception error){return Fail(error,false);}}
}
public static class HubSshMaintenanceBrokerEntry {
  static Dictionary<string,object> Probe(Dictionary<string,object> d,byte[] secret){string nonce=Guid.NewGuid().ToString("N");string cmd="/usr/bin/python3 -I -c 'import os;print(\"HUB_SSH_IDENTITY_V2:"+nonce+":\"+str(os.getuid())+\":\"+open(\"/proc/sys/kernel/random/boot_id\").read().strip())'";var r=HubSshMaintenanceTransport.Run(new HubSshMaintenanceTransport.Options{Ssh=(string)d["ssh"],Args=C.Args(d,cmd),Cwd=(string)d["root"],Helper=C.Self,Secret=secret,CaptureOutput=true,DeadlineMs=30000,EventSink=C.Event,HostFingerprint=(string)d["hostFingerprint"]});C.Require(r.CleanupVerified,"SSH_CLEANUP_UNVERIFIED");C.Require(r.ExitCode==0&&r.Authenticated&&r.AskpassSupplied,"SSH_AUTHENTICATION_UNVERIFIED");string text=C.Utf8.GetString(r.Output);Match m=Regex.Match(text,"\\AHUB_SSH_IDENTITY_V2:"+nonce+":([1-9][0-9]{0,8}):([a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12})\\r?\\n\\z");int uid;C.Require(m.Success&&Int32.TryParse(m.Groups[1].Value,out uid)&&uid>0&&m.Groups[2].Value!="00000000-0000-0000-0000-000000000000","REMOTE_IDENTITY_REJECTED");C.Event("IDENTITY_VERIFIED");return new Dictionary<string,object>{{"uid",Int32.Parse(m.Groups[1].Value)},{"bootId",m.Groups[2].Value}};}
  static void ValidateRunBeforeConnection(Dictionary<string,object> run,HubSshMaintenanceState state){C.Fields(run,"protocol","op","sequence","nonce","catalogSHA256","bootId","uid","case","expiresAtUnixSeconds","runtimeSeconds");C.Num(run,"protocol",1,1);C.Num(run,"sequence",1,1);C.Require(C.Str(run,"op",32)==HubSshMaintenanceCatalog.Operation&&C.Str(run,"case",32)=="isolation-v1"&&C.Str(run,"catalogSHA256",64)==HubSshMaintenanceCatalog.CatalogSHA256,"RUN_CATALOG_REJECTED");string nonce=C.Str(run,"nonce",64),boot=C.Str(run,"bootId",36);C.Require(Regex.IsMatch(nonce,"^[a-f0-9]{64}$")&&nonce!=new string('0',64),"RUN_NONCE_REJECTED");C.Require(Regex.IsMatch(boot,"^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$")&&boot!="00000000-0000-0000-0000-000000000000"&&C.Num(run,"uid",1,Int32.MaxValue)==state.Uid,"RUN_IDENTITY_CHANGED");C.Num(run,"runtimeSeconds",60,60);int expires=C.Num(run,"expiresAtUnixSeconds",1,Int32.MaxValue),now=HubSshMaintenanceState.Now();C.Require(expires>now&&expires<=now+120,"RUN_EXPIRED");C.Require(!C.Exists(Path.Combine(state.DestinationRoot,"run-"+nonce+".bin")),"RUN_NONCE_REPLAY");}
  static byte[] RunInput(Dictionary<string,object> run,HubSshMaintenanceState state,Dictionary<string,object> observed){C.Fields(run,"protocol","op","sequence","nonce","catalogSHA256","bootId","uid","case","expiresAtUnixSeconds","runtimeSeconds");C.Num(run,"protocol",1,1);C.Num(run,"sequence",1,1);C.Require(C.Str(run,"op",32)==HubSshMaintenanceCatalog.Operation&&C.Str(run,"case",32)=="isolation-v1"&&C.Str(run,"catalogSHA256",64)==HubSshMaintenanceCatalog.CatalogSHA256,"RUN_CATALOG_REJECTED");string nonce=C.Str(run,"nonce",64);C.Require(Regex.IsMatch(nonce,"^[a-f0-9]{64}$")&&nonce!=new string('0',64),"RUN_NONCE_REJECTED");C.Require(C.Num(run,"uid",1,Int32.MaxValue)==state.Uid&&C.Num(observed,"uid",1,Int32.MaxValue)==state.Uid&&C.Str(run,"bootId",36)==C.Str(observed,"bootId",36),"RUN_IDENTITY_CHANGED");C.Num(run,"runtimeSeconds",60,60);int expires=C.Num(run,"expiresAtUnixSeconds",1,Int32.MaxValue),now=HubSshMaintenanceState.Now();C.Require(expires>now&&expires<=now+120,"RUN_EXPIRED");byte[] payload=Convert.FromBase64String(HubSshMaintenanceCatalog.PayloadBase64);C.Require(payload.Length==HubSshMaintenanceCatalog.PayloadLength&&C.Hash(payload)==HubSshMaintenanceCatalog.PayloadSHA256,"EMBEDDED_PAYLOAD_CHANGED");byte[] request=C.Utf8.GetBytes(C.Canon(run));C.Require(request.Length<=4096,"RUN_FRAME_TOO_LARGE");byte[] input=new byte[payload.Length+4+request.Length];Buffer.BlockCopy(payload,0,input,0,payload.Length);int n=request.Length;input[payload.Length]=(byte)(n>>24);input[payload.Length+1]=(byte)(n>>16);input[payload.Length+2]=(byte)(n>>8);input[payload.Length+3]=(byte)n;Buffer.BlockCopy(request,0,input,payload.Length+4,request.Length);string receipt=Path.Combine(state.DestinationRoot,"run-"+nonce+".bin");C.CreateFile(receipt,C.Protected(C.Canon(new Dictionary<string,object>{{"version",1},{"manifestSHA256",state.ManifestHash},{"run",run}})));return input;}
  [STAThread] public static int Main(){if(Environment.GetEnvironmentVariable("HUB_SSH_VAULT_PIPE")!=null)return HubSshMaintenanceTransport.Askpass();bool raw=false;try{var req=HubSshMaintenanceEntry.Request();string mode=C.Str(req,"mode",32);raw=mode=="run-r2-synthetic-v1";bool validation=mode=="validate-migration";C.Require(mode=="status"||mode=="probe"||validation||raw,"MODE_REJECTED");if(validation)C.Fields(req,"mode","manifest","ordinal");else if(raw)C.Fields(req,"mode","manifest","runRequest");else C.Fields(req,"mode","manifest");using(var state=new HubSshMaintenanceState(req["manifest"] as Dictionary<string,object>,null,false)){
      if(validation){int ordinal=C.Num(req,"ordinal",1,2);HubSshMaintenanceProcess.Accept(state.Manifest,ordinal);}
      state.AcquireDestination();state.BrokerGate(validation);if(raw)ValidateRunBeforeConnection(req["runRequest"] as Dictionary<string,object>,state);if(mode=="status"){byte[] checkedSecret=state.DestinationSecret();Array.Clear(checkedSecret,0,checkedSecret.Length);Console.WriteLine(C.Canon(C.Result("active")));return 0;}
      byte[] secret=null,input=null;try{secret=state.DestinationSecret();var identity=Probe(state.Destination,secret);C.Require((int)identity["uid"]==state.Uid,"REMOTE_UID_CHANGED");if(!raw){var result=C.Result(validation?"validated":"connected");result["uid"]=identity["uid"];result["bootId"]=identity["bootId"];Console.WriteLine(C.Canon(result));return 0;}
        input=RunInput(req["runRequest"] as Dictionary<string,object>,state,identity);state.BrokerGate(false);var d=state.Destination;var r=HubSshMaintenanceTransport.Run(new HubSshMaintenanceTransport.Options{Ssh=(string)d["ssh"],Args=C.Args(d,HubSshMaintenanceCatalog.Command),Cwd=(string)d["root"],Helper=C.Self,Secret=secret,CaptureOutput=false,FixedInput=input,DeadlineMs=HubSshMaintenanceCatalog.RunDeadlineMs,EventSink=C.Event,HostFingerprint=(string)d["hostFingerprint"]});C.Require(r.CleanupVerified,"SSH_CLEANUP_UNVERIFIED");C.Require(r.ExitCode==0&&r.Authenticated&&r.AskpassSupplied,"R2_SSH_FAILED");C.Event("R2_SSH_EXIT_0");return 0;
      }finally{if(secret!=null)Array.Clear(secret,0,secret.Length);if(input!=null)Array.Clear(input,0,input.Length);}
    }}catch(Exception error){return HubSshMaintenanceEntry.Fail(error,raw);}}
}
